package secondproject;

public class ArrayExample2 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int[] sAges = {12,21,22,23,24,26,27};
		for(int i=0; i<sAges.length;i++)
		System.out.println(sAges[i]);
		System.out.println(sAges.length);
		 
		char[] sGrades = {'A','B','C'};
		for(int i=0; i<sGrades.length;i++)
		System.out.println(sGrades[i]);
		System.out.println(sGrades.length);

	}

}
